WITH "__duckstream_0" AS (SELECT t.c14 AS c0, t.c2 AS c1, CASE WHEN (t.c3 = 'home') THEN t.c11 ELSE t.c12 END AS c2, CASE WHEN t.c8 THEN CAST(0 AS INTEGER) ELSE CAST(1 AS INTEGER) END AS c3, CASE WHEN ((NOT t.c8) AND (t.c4 = CAST(0 AS INTEGER))) THEN CAST(1 AS INTEGER) ELSE CAST(0 AS INTEGER) END AS c4, CASE WHEN ((NOT t.c8) AND (t.c4 > CAST(0 AS INTEGER))) THEN CAST(1 AS INTEGER) ELSE CAST(0 AS INTEGER) END AS c5, CASE WHEN t.c8 THEN CAST(1 AS INTEGER) ELSE CAST(0 AS INTEGER) END AS c6, CASE WHEN t.c8 THEN CAST(0 AS INTEGER) ELSE CAST((COALESCE(t.c5, CASE WHEN (t.c4 > CAST(90 AS INTEGER)) THEN t.c4 ELSE CAST(90 AS INTEGER) END) - t.c4) AS INTEGER) END AS c7, CASE WHEN t.c6 THEN CAST(1 AS INTEGER) ELSE CAST(0 AS INTEGER) END AS c8, CASE WHEN t.c7 THEN CAST(1 AS INTEGER) ELSE CAST(0 AS INTEGER) END AS c9 FROM (SELECT t.c2 AS c0, t.c3 AS c1, t.c4 AS c2, t.c5 AS c3, t.c6 AS c4, t.c7 AS c5, t.c8 AS c6, t.c9 AS c7, t.c10 AS c8, t.c11 AS c9, t.c12 AS c10, t.c13 AS c11, t.c14 AS c12, t.c0 AS c13, t.c1 AS c14 FROM (SELECT l.c0 AS c0, l.c1 AS c1, r.c0 AS c2, r.c1 AS c3, r.c2 AS c4, r.c3 AS c5, r.c4 AS c6, r.c5 AS c7, r.c6 AS c8, r.c7 AS c9, r.c8 AS c10, r.c9 AS c11, r.c10 AS c12, r.c11 AS c13, r.c12 AS c14 FROM (SELECT "id" AS c0, "championship_id" AS c1 FROM "source_phase") l INNER JOIN (SELECT t.c4 AS c0, t.c5 AS c1, t.c6 AS c2, t.c7 AS c3, t.c8 AS c4, t.c9 AS c5, t.c10 AS c6, t.c11 AS c7, t.c12 AS c8, t.c0 AS c9, t.c1 AS c10, t.c2 AS c11, t.c3 AS c12 FROM (SELECT l.c0 AS c0, l.c1 AS c1, l.c2 AS c2, l.c3 AS c3, r.c0 AS c4, r.c1 AS c5, r.c2 AS c6, r.c3 AS c7, r.c4 AS c8, r.c5 AS c9, r.c6 AS c10, r.c7 AS c11, r.c8 AS c12 FROM (SELECT "id" AS c0, "phase_id" AS c1, "home_id" AS c2, "away_id" AS c3 FROM "source_game") l INNER JOIN (SELECT "id" AS c0, "game_id" AS c1, "player_id" AS c2, "side" AS c3, "on_minute" AS c4, "off_minute" AS c5, "yellow" AS c6, "red" AS c7, "bench" AS c8 FROM "source_player_game") r ON (l.c0 = r.c1)) t) r ON (l.c0 = r.c10)) t) t),
"__duckstream_1" AS ((SELECT t.c0 AS c0, t.c1 AS c1, t.c2 AS c2, t.c3 AS c3, t.c4 AS c4, t.c5 AS c5, t.c6 AS c6, CASE WHEN (t.c7 > CAST(0 AS INTEGER)) THEN t.c7 ELSE CAST(0 AS INTEGER) END AS c7, CAST(0 AS INTEGER) AS c8, CAST(0 AS INTEGER) AS c9, CAST(0 AS INTEGER) AS c10, t.c8 AS c11, t.c9 AS c12 FROM (SELECT v.c0 AS c0, v.c1 AS c1, v.c2 AS c2, v.c3 AS c3, v.c4 AS c4, v.c5 AS c5, v.c6 AS c6, v.c7 AS c7, v.c8 AS c8, v.c9 AS c9 FROM "__duckstream_0" v) t) UNION ALL (SELECT t.c11 AS c0, t.c2 AS c1, CASE WHEN ((t.c3 = 'home') <> t.c5) THEN t.c8 ELSE t.c9 END AS c2, CAST(0 AS INTEGER) AS c3, CAST(0 AS INTEGER) AS c4, CAST(0 AS INTEGER) AS c5, CAST(0 AS INTEGER) AS c6, CAST(0 AS INTEGER) AS c7, CASE WHEN t.c5 THEN CAST(0 AS INTEGER) ELSE CAST(1 AS INTEGER) END AS c8, CASE WHEN (t.c4 AND (NOT t.c5)) THEN CAST(1 AS INTEGER) ELSE CAST(0 AS INTEGER) END AS c9, CASE WHEN t.c5 THEN CAST(1 AS INTEGER) ELSE CAST(0 AS INTEGER) END AS c10, CAST(0 AS INTEGER) AS c11, CAST(0 AS INTEGER) AS c12 FROM (SELECT t.c2 AS c0, t.c3 AS c1, t.c4 AS c2, t.c5 AS c3, t.c6 AS c4, t.c7 AS c5, t.c8 AS c6, t.c9 AS c7, t.c10 AS c8, t.c11 AS c9, t.c0 AS c10, t.c1 AS c11 FROM (SELECT l.c0 AS c0, l.c1 AS c1, r.c0 AS c2, r.c1 AS c3, r.c2 AS c4, r.c3 AS c5, r.c4 AS c6, r.c5 AS c7, r.c6 AS c8, r.c7 AS c9, r.c8 AS c10, r.c9 AS c11 FROM (SELECT "id" AS c0, "championship_id" AS c1 FROM "source_phase") l INNER JOIN (SELECT t.c4 AS c0, t.c5 AS c1, t.c6 AS c2, t.c7 AS c3, t.c8 AS c4, t.c9 AS c5, t.c0 AS c6, t.c1 AS c7, t.c2 AS c8, t.c3 AS c9 FROM (SELECT l.c0 AS c0, l.c1 AS c1, l.c2 AS c2, l.c3 AS c3, r.c0 AS c4, r.c1 AS c5, r.c2 AS c6, r.c3 AS c7, r.c4 AS c8, r.c5 AS c9 FROM (SELECT "id" AS c0, "phase_id" AS c1, "home_id" AS c2, "away_id" AS c3 FROM "source_game") l INNER JOIN (SELECT "id" AS c0, "game_id" AS c1, "player_id" AS c2, "side" AS c3, "penalty" AS c4, "own_goal" AS c5 FROM "source_goal") r ON (l.c0 = r.c1)) t) r ON (l.c0 = r.c7)) t) t)),
